const searchInput = document.getElementById('search-input');
const searchSuggestions = document.getElementById('search-suggestions');

searchInput.addEventListener('input', async () => {
  const query = searchInput.value.trim();
  if (query.length > 2) {
    const response = await fetch(`https://www.googleapis.com/customsearch/v1?key=YOUR_API_KEY&cx=YOUR_SEARCH_ENGINE_ID&q=${query}`);
    const suggestions = await response.json();
    const suggestionList = document.createElement('ul');
    suggestions.items.forEach((suggestion) => {
      const suggestionListItem = document.createElement('li');
      suggestionListItem.textContent = suggestion.title;
      suggestionList.appendChild(suggestionListItem);
    });
    searchSuggestions.appendChild(suggestionList);
  } else {
    searchSuggestions.innerHTML = '';
  }
});
```

